/** Job model shared by the server and the worker. */

export const STEP_MS = 100;
/** Delay before a failed attempt is retried. Must be between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
/** Total attempts allowed, including the first. */
export const MAX_ATTEMPTS = 3;
export const MAX_INPUT_LENGTH = 1000;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Row shape of the `jobs` table. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** Job as returned by the HTTP API. */
export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): JobJson {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Validates a parsed request body. Returns the job parameters with defaults applied, or the field errors. */
export function validateNewJob(body: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const obj = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: `Unknown field "${key}".` });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string.' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters.` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
  }

  const steps = obj.steps === undefined ? DEFAULT_STEPS : obj.steps;
  if (!isIntegerInRange(steps, 1, MAX_STEPS)) {
    fields.push({ field: 'steps', message: `steps must be an integer from 1 to ${MAX_STEPS}.` });
  }

  const failAttempts = obj.failAttempts === undefined ? DEFAULT_FAIL_ATTEMPTS : obj.failAttempts;
  if (!isIntegerInRange(failAttempts, 0, MAX_FAIL_ATTEMPTS)) {
    fields.push({ field: 'failAttempts', message: `failAttempts must be an integer from 0 to ${MAX_FAIL_ATTEMPTS}.` });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function isIntegerInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

