import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { all, get, openDatabase, run } from './db.ts';
import { toJob, validateNewJob, type FieldError, type JobJson, type JobRow } from './jobs.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;

const db: DatabaseSync = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function isJsonContentType(value: string | undefined): boolean {
  if (!value) return false;
  return value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

type BodyResult = { ok: true; text: string } | { ok: false };

/** Reads the whole request body, up to MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<BodyResult> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { ok: false } : { ok: true, text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function findByKey(key: string): JobRow | undefined {
  return get<JobRow>(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const keyHeader = req.headers['idempotency-key'];
  const idempotencyKey = Array.isArray(keyHeader) ? keyHeader.join(', ') : keyHeader;
  const bodyResult = await readBody(req);

  const fields: FieldError[] = [];
  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (!bodyResult.ok) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(bodyResult.text);
    } catch {
      parseOk = false;
    }
    if (!parseOk) {
      fields.push({ field: 'body', message: 'Request body is not valid JSON.' });
    } else {
      const validated = validateNewJob(parsed);
      if (!validated.ok) {
        fields.push(...validated.fields);
      } else if (fields.length === 0) {
        const payload = validated.value;
        if (idempotencyKey !== undefined) {
          const existing = findByKey(idempotencyKey);
          if (existing) {
            if (existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts) {
              sendJson(res, 200, toJob(existing));
            } else {
              sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
